using namespace std;


char encoder[26] = {'C','S','P',0};

char decoder[26];


string st;


int main()  {

  int k = 0;

  for (int i = 0; i < 26; ++i)

    if (encoder[i] != 0) ++k;

  for (char x ='A'; x <= 'Z'; ++x) {

    bool flag = true;

    for (int i = 0; i < 26; ++i)

      if (encoder[i] ==x) {

        flag = false;

        break;

      }

      if (flag) {

        encoder[k]= x;

        ++k;

      }

  }

  for (int i = 0; i < 26; ++i)

     decoder[encoder[i]- 'A'] = i + 'A';

  cin >> st;

  for (int i = 0; i < st.length( ); ++i)

    st[i] = decoder[st[i] -'A'];

  cout << st;

  return 0;

}

#include <iostream>

using namespace std;


long long n, ans;

int k, len;

long long d[1000000];


int main() {

  cin >> n >> k;

  d[0] = 0;

  len= 1;

  ans = 0;

  for (long long i = 0; i <n; ++i) {

    ++d[0];

    for (int j = 0; j + 1<len; ++j) {

      if (d[j] == k) {

        d[j] = 0;

        d[j + 1] += 1;

        ++ans;

      }

    }

    if (d[len- 1] == k) {

      d[len - 1] = 0;

      d[len] =1;

      ++len;

      ++ans;

    }

  }

  cout << ans << endl;

  return 0;

}

